        label.new(bar_index, high, 'Sydney', style=label.style_label_down, color=sydneyColor)`,inputs:[{name:"Highlight NY",type:"boolean",defaultVal:"true"},{name:"Highlight London",type:"boolean",defaultVal:"true"}],alerts:[]},{id:"smart_money_toolkit",name:"GQR Smart Money Toolkit",description:"An all-in-one Smart Money indicator featuring Market Structure Shifts (MSS), Break of Structure (BOS), Order Blocks (OB) highlighting, Fair Value Gaps (FVG) detection, Liquidity pools, and optional session backgrounds.",category:"Smart Money Concepts",code:`//@version=5
